import{z as i,x as o,o as A,c as C,q as r,j as s,D as t,d as e,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CAP 与 PACELC","description":"","frontmatter":{"title":"CAP 与 PACELC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cap-pacelc.md","filePath":"cs/cap-pacelc.md","lastUpdated":1791063341000}'),p={name:"cs/cap-pacelc.md"};function d(c,a,P,D,m,F){const n=o("Mermaid");return A(),C("div",null,[a[2]||(a[2]=r('<h1 id="cap-与-pacelc" tabindex="-1">CAP 与 PACELC <a class="header-anchor" href="#cap-与-pacelc" aria-label="Permalink to &quot;CAP 与 PACELC&quot;">​</a></h1><div class="epigraph"><p>分区发生时，线性一致与可用性不可兼得。没有分区时，延迟与一致仍要交换——PACELC 把这后半句写进缩写。</p><footer>—— 据 Gilbert and Lynch, Brewer&#39;s Conjecture and the Feasibility of Consistent, Available, Partition-Tolerant Web Services, SIGACT News 2002；Abadi, Consistency Tradeoffs in Modern Distributed Database Design, IEEE Computer 2012；Brewer, 2012 回顾 整理</footer></div><p>上一课<a href="/cs/eventual-consistency">最终一致</a>是许多人在分区下的选择。缺口是<strong>为什么必须选</strong>：不是性格，是定理。本课不重写线性化点，不把 Dynamo 当 CAP 的唯一例。后课主备、法定人数都是在这张表里占格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Brewer 的猜想：一致、可用、分区容忍三选二。Gilbert–Lynch 把它证成：在异步网络分区下，<strong>线性一致</strong>与<strong>每个请求都终止</strong>不能同时。可用这里指正确节点在有限步返回（不无限等另一分区）。分区指信道把节点切成互不通信的组。</p><p>缺口：三选二被误读成「永远只能挑两字」。没有分区时三者可以同时（单主、多数派在连通时）。真正日常交换是<strong>延迟 vs 一致</strong>。Abadi 的 PACELC：If Partition, then A or C Else Latency or C。</p><p><span class="marginnote">术语翻译：PACELC 就是把两句话压进一个缩写——分区时（P）在可用与一致之间选；否则（EL, Else Latency）在延迟与一致之间选。它不引入新定理，只是提醒你「没有分区也在做交换」。</span></p><p><span class="marginnote">Gilbert–Lynch 的 C 是线性一致，不是「数据没丢」。A 不是 HTTP 200。弱一致模型可以在分区下既「可用」又「某种 C」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计时先问：分区期间读是否必须线性化？若是，少数派必须拒绝（CP）。若否，就近返回（AP），愈合时合并。再问：无分区时是否同步复制到多数派（偏 C、加延迟）还是异步（偏 L）。</p>',10)),(A(),s(l,null,{default:t(()=>[B(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%7B%22%E5%8F%91%E7%94%9F%E5%88%86%E5%8C%BA%3F%22%7D%20--%3E%7C%22%E6%98%AF%22%7C%20AC%5B%22%E9%80%89%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%E6%88%96%E9%80%89%E5%A7%8B%E7%BB%88%E8%BF%94%E5%9B%9E%22%5D%0A%20%20P%20--%3E%7C%22%E5%90%A6%22%7C%20EL%5B%22%E9%80%89%E5%A4%9A%E5%89%AF%E6%9C%AC%E7%A1%AE%E8%AE%A4%E5%BB%B6%E8%BF%9F%E6%88%96%E9%80%89%E5%BC%B1%E8%AF%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要用 CAP 解释 FLP：一个是分区+线性一致读写，一个是异步崩溃+共识终止。不要用 CAP 解释磁盘满。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("多数派读写：\\(R+W\\gt n\\) 在"),E("strong",null,"未分区"),e("时给线性一致寄存器（后课 quorum）。分区导致多数派只在一侧，另一侧的 W 或 R 不能完成——这是 CP。Dynamo 式 \\(R+W\\le n\\) 或斜向就近：分区两侧都能写，AP，冲突后课解决。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：n=3 取 R=2、W=2，读写集合大小之和 2+2=4\\gt 3，必有一个副本同时参与读和写，所以总能读到最新已确认的值；若改成 W=1，写入一落地就返回，慢的那份副本就可能被读到旧值。")],-1)),(A(),s(l,null,{default:t(()=>[B(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22n%3D3%EF%BC%8C%E5%8F%96%20R%3D2%20%E4%B8%8E%20W%3D2%22%5D%20--%3E%20OK%5B%22%E8%BF%9E%E9%80%9A%E6%97%B6%EF%BC%9A2%20%E4%B8%AA%E7%A1%AE%E8%AE%A4%E5%8D%B3%E5%8F%AF%E8%AF%BB%E5%86%99%22%5D%0A%20%20Q%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%EF%BC%9AA%2CB%20%E5%9C%A8%E4%B8%80%E4%BE%A7%EF%BC%8CC%20%E5%8D%95%E7%8B%AC%E4%B8%80%E4%BE%A7%22%5D%0A%20%20PART%20--%3E%20SIDE1%5B%22A%2CB%20%E4%BE%A7%E6%9C%89%202%20%E5%8F%B0%EF%BC%9A%E5%87%91%E6%88%90%E5%A4%9A%E6%95%B0%EF%BC%8C%E7%BB%A7%E7%BB%AD%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20PART%20--%3E%20SIDE2%5B%22C%20%E4%BE%A7%E5%8F%AA%E6%9C%89%201%20%E5%8F%B0%EF%BC%9A%E5%87%91%E4%B8%8D%E9%BD%90%E5%A4%9A%E6%95%B0%22%5D%0A%20%20SIDE1%20--%3E%20CP%5B%22%E5%88%86%E5%8C%BA%E4%B8%8B%E4%BB%8D%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%EF%BC%9ACP%20%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20SIDE2%20--%3E%20AP%5B%22%E8%8B%A5%E6%94%BE%E5%AE%BD%20W%3D1%EF%BC%8C%E4%B8%A4%E4%BE%A7%E9%83%BD%E8%83%BD%E5%86%99%EF%BC%9AAP%20%E8%B7%AF%E7%BA%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>PACELC 的 EL：同步流水线 vs 读本地。Spanner 选 C 与较高延迟；许多缓存选 L。缩写是备忘录，不是新定理；定理仍是 Gilbert–Lynch 加上延迟模型。</p><p>本课不把「CA」系统写成第三类宗教：拒绝承认分区等于假设网络永不切，Lynch 模型里这不成立。工程上「单机房、分区当全死」是把 P 的范围缩小。</p><p><span class="marginnote">常见误区：初学者容易把「CA 系统」当成与 CP、AP 并列的第三类选项，实际上「拒绝分区可能」等于假设网络永不切断——单机房系统只是把 P 的范围缩小成「机房整体死活」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PACELC 的所有数据库厂商对照表。不引入拜占庭分区。后课默认：协议声明分区时拒绝还是就近；连通时等多数派还是异步。主备切换是 CP 的一种实现形状。</p><p>口号去掉之后，留下的是线性一致与终止在分区下的合取不可能。选弱尺子才能两边返回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gilbert–Lynch：分区下线性一致与普遍终止不可兼得。</li><li>无分区时仍有延迟–一致交换：PACELC。</li><li>C 指线性一致；弱模型不在该不可能式里。</li><li>出处：Gilbert and Lynch, 2002；Abadi, 2012；Brewer 回顾。</li></ul>',8))])}const b=i(p,[["render",d]]);export{u as __pageData,b as default};
